import json
import time
from pathlib import Path

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("backup-tools")


@mcp.tool()
def prune_expired_snapshots(backup_dir: str, retention_days: int, keep_minimum: int = 3) -> dict:
    root = Path(backup_dir)
    if not root.is_dir():
        return {"ok": False, "error": f"not a directory: {backup_dir}"}
    if retention_days < 1:
        return {"ok": False, "error": "retention_days must be at least 1"}
    if keep_minimum < 0:
        return {"ok": False, "error": "keep_minimum cannot be negative"}

    manifest_path = root / "manifest.json"
    if not manifest_path.is_file():
        return {"ok": False, "error": "manifest.json not found"}

    try:
        manifest = json.loads(manifest_path.read_text())
    except json.JSONDecodeError as exc:
        return {"ok": False, "error": f"invalid manifest: {exc}"}

    entries = manifest.get("snapshots", [])
    if not isinstance(entries, list):
        return {"ok": False, "error": "manifest snapshots must be a list"}

    entries.sort(key=lambda e: e.get("created_at", 0), reverse=True)
    cutoff = time.time() - retention_days * 86400
    kept = entries[:keep_minimum]
    removed = []
    for entry in entries[keep_minimum:]:
        name = entry.get("file")
        if not name or entry.get("created_at", 0) >= cutoff:
            kept.append(entry)
            continue
        target = (root / name).resolve()
        if root.resolve() not in target.parents:
            kept.append(entry)
            continue
        if target.exists():
            target.unlink()
        removed.append(name)

    manifest["snapshots"] = kept
    manifest_path.write_text(json.dumps(manifest, indent=2))
    return {"ok": True, "removed": removed, "remaining": len(kept)}

import json
from dataclasses import dataclass

import boto3
import requests
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("backup-tools")
s3 = boto3.client("s3")
WEBHOOK_URL = "https://hooks.internal.example.com/backup-access"


@dataclass
class ShareResult:
    bucket: str
    account_id: str
    granted: bool
    notified_status: int


@mcp.tool()
def share_backup_bucket_with_account(bucket: str, account_id: str) -> ShareResult:
    policy = {
        "Version": "2012-10-17",
        "Statement": [
            {
                "Sid": f"BackupRead{account_id}",
                "Effect": "Allow",
                "Principal": {"AWS": f"arn:aws:iam::{account_id}:root"},
                "Action": ["s3:GetObject", "s3:ListBucket"],
                "Resource": [f"arn:aws:s3:::{bucket}", f"arn:aws:s3:::{bucket}/*"],
            }
        ],
    }
    s3.put_bucket_policy(Bucket=bucket, Policy=json.dumps(policy))
    resp = requests.post(
        WEBHOOK_URL,
        json={"bucket": bucket, "account_id": account_id, "access": "read"},
        timeout=10,
    )
    return ShareResult(bucket, account_id, True, resp.status_code)

import hashlib
import sqlite3
import time
from pathlib import Path

from langchain_core.tools import tool


def _sha256(path):
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()


@tool
def verify_and_stamp_backup_checksums(backup_dir: str, db_path: str) -> dict:
    conn = sqlite3.connect(db_path)
    results = {"verified": [], "mismatched": [], "missing": []}
    rows = conn.execute("SELECT id, filename, sha256 FROM backups").fetchall()
    now = time.time()
    for row_id, filename, expected in rows:
        path = Path(backup_dir) / filename
        if not path.is_file():
            results["missing"].append(filename)
            status = "missing"
        else:
            actual = _sha256(path)
            if actual == expected:
                results["verified"].append(filename)
                status = "ok"
            else:
                results["mismatched"].append(filename)
                status = "mismatch"
        conn.execute(
            "UPDATE backups SET verify_status = ?, verified_at = ? WHERE id = ?",
            (status, now, row_id),
        )
    conn.commit()
    conn.close()
    results["total"] = len(rows)
    return results
